-- 6) Conferência
select count(*) as pontos from public.pontos_coleta;
select count(*) as vinculos from public.ponto_residuos;
select count(*) as horarios from public.horarios_funcionamento;
select count(*) filter (where telefone is not null) as com_telefone from public.pontos_coleta;
select count(*) as sem_residuo
from public.pontos_coleta p
where not exists (select 1 from public.ponto_residuos pr where pr.ponto_id = p.id);
